import{_ as o,o as t,c as n,ae as r}from"./chunks/framework.vXWZTEWX.js";const p=JSON.parse('{"title":"ADR 036: Vercel Frontend Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"adr/036-vercel-frontend-deployment.md","filePath":"adr/036-vercel-frontend-deployment.md"}'),a={name:"adr/036-vercel-frontend-deployment.md"};function i(l,e,d,s,c,u){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-036-vercel-frontend-deployment" tabindex="-1">ADR 036: Vercel Frontend Deployment <a class="header-anchor" href="#adr-036-vercel-frontend-deployment" aria-label="Permalink to &quot;ADR 036: Vercel Frontend Deployment&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>We initially deployed the entire application (frontend and backend) on Render. However, to improve frontend performance, take advantage of Vercel&#39;s global CDN, and use a custom subdomain (<code>tendercheckai.elecodes.online</code>), we decided to move the frontend to Vercel while keeping the backend and database on Render/Turso. This also solves the &quot;sleep&quot; issue for the UI, as Vercel is always active, even if the backend needs a few seconds to wake up.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Deploy the React frontend on Vercel using the following configuration:</p><ol><li><strong>SPA Routing</strong>: Use <code>vercel.json</code> with a rewrite rule to redirect all non-file requests to <code>index.html</code>.</li><li><strong>Environment Variables</strong>: <ul><li><code>VITE_API_BASE_URL</code>: Pointing to the Render backend (<code>https://tendercheck-backend.onrender.com</code>).</li><li><code>VITE_GOOGLE_CLIENT_ID</code>: For OAuth.</li><li><code>VITE_ENABLE_GOOGLE_AUTH</code>: A feature flag to control the visibility of the Google login button. This allows us to disable the button if the OAuth quota is exceeded or if maintenance is required without rebuilding the app.</li></ul></li><li><strong>Cross-Origin Configuration</strong>: Update the Render backend&#39;s <code>ALLOWED_ORIGINS</code> to include: <ul><li><code>https://tendercheckai.elecodes.online</code></li><li><code>https://tender-check-ai.vercel.app</code></li></ul></li><li><strong>Google OAuth</strong>: Register the new Vercel URLs in the Google Cloud Console as authorized origins and redirect URIs.</li><li><strong>DNS Configuration</strong>: Set up a <code>CNAME</code> record for <code>tendercheckai</code> pointing to <code>cname.vercel-dns.com</code>.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Improved Performance</strong>: Frontend assets are served via Vercel&#39;s Edge Network, ensuring instant initial load.</li><li><strong>Better UX</strong>: The UI is always available, providing immediate feedback even if the backend is currently scaling up.</li><li><strong>Custom Branding</strong>: Professional subdomain under <code>elecodes.online</code>.</li><li><strong>Complexity</strong>: We now manage two deployment platforms (Vercel for frontend, Render for backend).</li><li><strong>Security</strong>: CORS must be explicitly managed to allow communication between the two platforms.</li><li><strong>Cost</strong>: Both Vercel and Render have generous free tiers that fit our current needs.</li></ul>',10)])])}const g=o(a,[["render",i]]);export{p as __pageData,g as default};
